  ('ae763884-2439-5c07-8360-9ff4c3823709', '22222222-2222-2222-2222-222222222211', 'short', '和模型 𝑓(𝑥) = |𝑥−𝑎| + |𝑥−𝑏|：（盒子模型） ①几何意义：表示在数轴上𝑥点到𝑎点与𝑏点的距离之和. ②最值情况： 𝑥在到𝑎与𝑏之间时,可取最小值|𝑏−𝑎|；无最大值. 拓展：设𝒂<𝒃<𝒄, 𝒇(𝒙) = |𝒙−𝒂| + |𝒙−𝒃| + |𝒙−𝒄|，𝒙= 𝒃时，𝒇(𝒙)可取最 小值|𝒄−𝒂|，无最大值. 你的坚持，终将美好！ 32', null, '', '', '数学/第1章 算术3 合订版.pdf', 6, true, 133, null),
  ('ef67a9a5-c615-5325-b725-8f8d7cb6a23d', '22222222-2222-2222-2222-222222222211', 'short', '差模型 𝑓(𝑥) = |𝑥−𝑎| −|𝑥−𝑏|：（Z 字型） ①几何意义：表示在数轴上𝑥点到𝑎点与𝑏点的距离之差. ②最值情况：𝑥在到𝑎与𝑏之外时,可取最小值−|𝑏−𝑎|,最大值|𝑏−𝑎|. 题型1：考查绝对值的和模型', null, '', '', '数学/第1章 算术3 合订版.pdf', 7, true, 134, null),
  ('8d1dad44-4c12-5ad6-9e0c-3535c4ee6e92', '22222222-2222-2222-2222-222222222211', 'mcq', '𝑓(𝑥) = |𝑥−2| + |𝑥−7|的最小值为( ).', '[{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}, {"key": "E", "text": "7"}]'::jsonb, '', '', '数学/第1章 算术3 合订版.pdf', 7, true, 135, null),
  ('00fcb87e-d4aa-5ce4-bbdf-c264f1c32611', '22222222-2222-2222-2222-222222222211', 'mcq', '方程𝑓(𝑥) = |𝑥+ 1| + |𝑥−2| + |𝑥−3|的最小值为( ).', '[{"key": "A", "text": "0"}, {"key": "B", "text": "1"}, {"key": "C", "text": "2"}, {"key": "D", "text": "3"}, {"key": "E", "text": "4"}]'::jsonb, '', '', '数学/第1章 算术3 合订版.pdf', 9, true, 136, null),
  ('3b812c8e-e435-5fff-a118-950db2946c2b', '22222222-2222-2222-2222-222222222211', 'mcq', '设𝑦= |𝑥−𝑎| + |𝑥−20| + |𝑥−𝑎−20|，其中0 < 𝑎< 20，则对于满 足𝑎⩽𝑥⩽20 的𝑥值，𝑦的最小值是( ).', '[{"key": "A", "text": "10"}, {"key": "B", "text": "15"}, {"key": "C", "text": "20"}, {"key": "D", "text": "25"}, {"key": "E", "text": "30"}]'::jsonb, '', '', '数学/第1章 算术3 合订版.pdf', 9, true, 137, null),
  ('cc504b95-016a-5f7a-b2dd-710d46dfed80', '22222222-2222-2222-2222-222222222211', 'mcq', '𝑓(𝑥) = |𝑥−2| −|𝑥−5|的最大值和最小值为( ).', '[{"key": "A", "text": "3,4"}, {"key": "B", "text": "3, −7"}, {"key": "C", "text": "4, −3"}, {"key": "D", "text": "4, −5"}, {"key": "E", "text": "3, −3"}]'::jsonb, '', '', '数学/第1章 算术3 合订版.pdf', 11, true, 138, null),
  ('b08ee6d9-2341-5063-8ddf-3539a03f32c8', '22222222-2222-2222-2222-222222222211', 'mcq', '求满足关系式|𝑥−3| −|𝑥+ 1|＝4 的𝑥的取值范围( ).', '[{"key": "A", "text": "𝑥⩽−2"}, {"key": "B", "text": "𝑥⩽1"}, {"key": "C", "text": "𝑥⩾−1"}, {"key": "D", "text": "𝑥⩾1"}, {"key": "E", "text": "𝑥⩽−1"}]'::jsonb, '', '', '数学/第1章 算术3 合订版.pdf', 11, true, 139, null),
  ('dd315462-fb56-5b6b-b576-d3836687c237', '22222222-2222-2222-2222-222222222211', 'short', '设𝑎是实数，𝑓(𝑥) = |𝑥−𝑎| −|𝑥−1|，则𝑓(𝑥) ⩽1.', null, '', '', '数学/第1章 算术3 合订版.pdf', 13, true, 140, null),
  ('005dba5f-983a-51c6-9961-c1714b40f04f', '22222222-2222-2222-2222-222222222211', 'short', '𝑎⩾0.', null, '', '', '数学/第1章 算术3 合订版.pdf', 13, true, 141, null),
  ('ca4b606e-137e-52aa-ac78-fa964dd72f18', '22222222-2222-2222-2222-222222222211', 'short', '𝑎⩽2. 【注】𝑭(𝒙) ⩽𝑨恒成立⇔𝑭(𝒙)𝐦𝐚𝐱⩽𝑨；𝑭(𝒙) ⩽𝑨有解⇔𝑭(𝒙)𝐦𝐢𝐧⩽𝑨. 你的坚持，终将美好！ 39 考点8：绝对值三角不等式（重点）', null, '', '', '数学/第1章 算术3 合订版.pdf', 13, true, 142, null),
  ('aafcb7bf-7a44-586c-98e1-3dab241d0667', '22222222-2222-2222-2222-222222222211', 'short', '基本形式 ||𝑎| −|𝑏|| ⩽|𝑎± 𝑏| ⩽|𝑎| + |𝑏|,（𝑎, 𝑏是任意实数） 对于右边部分：|𝑎+ 𝑏| = |𝑎| + |𝑏|，在𝑎𝑏⩾0 时成立； |𝑎−𝑏| = |𝑎| + |𝑏|，在𝑎𝑏⩽0 时成立. 口诀：和的绝对值小于等于绝对值之和，大于等于绝对值之差. 推广形式：|𝒂𝟏+ 𝒂𝟐+ ⋯+ 𝒂𝒏| ⩽|𝒂𝟏| + |𝒂𝟐| + ⋯+ |𝒂𝒏|. 推导： |𝑎+ 𝑏|2 = (𝑎+ 𝑏)2 = 𝑎2 + 𝑏2 + 2𝑎𝑏，(|𝑎| + |𝑏|)2 = 𝑎2 + 𝑏2 + 2|𝑎||𝑏|， 𝑎𝑏⩽|𝑎||𝑏|，故恒有|𝑎+ 𝑏| ⩽|𝑎| + |𝑏|. |𝑎−𝑏|2 = (𝑎−𝑏)2 = 𝑎2 + 𝑏2 −2𝑎𝑏，(|𝑎| + |𝑏|)2 = 𝑎2 + 𝑏2 + 2|𝑎||𝑏|， −𝑎𝑏⩽|𝑎||𝑏|，故恒有|𝑎−𝑏| ⩽|𝑎| + |𝑏|. |𝑎| = |𝑎+ 𝑏−𝑏| ⩽|𝑎+ 𝑏| + |𝑏| ⇒ |𝑎| −|𝑏| ⩽|𝑎+ 𝑏|， |𝑏| = |𝑏+ 𝑎−𝑎| ⩽|𝑎+ 𝑏| + |𝑎| ⇒ |𝑏| −|𝑎| ⩽|𝑎+ 𝑏|， 合起来得：||𝑎| −|𝑏|| ⩽|𝑎+ 𝑏|.', null, '', '', '数学/第1章 算术3 合订版.pdf', 14, true, 143, null),
  ('ab9f2b07-7b50-5f13-901b-0eda18cb78cd', '22222222-2222-2222-2222-222222222211', 'short', '变式形式', null, '', '', '数学/第1章 算术3 合订版.pdf', 14, true, 144, null),
  ('0fb3440f-9127-508e-9328-55f8c7709d6d', '22222222-2222-2222-2222-222222222211', 'short', '|𝑥−𝑦| = |(𝑥−𝑎) + (𝑎−𝑦)| ⩽|𝑥−𝑎| + |𝑎−𝑦|.', null, '', '', '数学/第1章 算术3 合订版.pdf', 14, true, 145, null),
  ('6f26cd78-4b7b-5a0e-b50c-0451c46b3d2b', '22222222-2222-2222-2222-222222222211', 'short', '|𝑥−𝑦| = |(𝑥−𝑎) + (𝑎−𝑏) + (𝑏−𝑦)| ⩽|𝑥−𝑎| + |𝑎−𝑏| + |𝑏−𝑦|.', null, '', '', '数学/第1章 算术3 合订版.pdf', 14, true, 146, null),
  ('e60b70e1-1357-5ad2-a5de-1f06cb15fd26', '22222222-2222-2222-2222-222222222211', 'short', 'max{𝑎, 𝑏} = 𝑎+ 𝑏+ |𝑎−𝑏| 2 .', null, '', '', '数学/第1章 算术3 合订版.pdf', 14, true, 147, null),
  ('b5afb1af-97dd-536e-8f46-4de8f0f22b1e', '22222222-2222-2222-2222-222222222211', 'short', 'min{𝑎, 𝑏} = 𝑎+ 𝑏−|𝑎−𝑏| 2 . 你的坚持，终将美好！ 40 题型1：考查恒成立时解的情况', null, '', '', '数学/第1章 算术3 合订版.pdf', 14, true, 148, null),
  ('ff330b76-03dd-5cbb-9347-a976a43a0f7a', '22222222-2222-2222-2222-222222222211', 'short', '不等式|𝑥−2| + |4 −𝑥| < 𝑠无解.', null, '', '', '数学/第1章 算术3 合订版.pdf', 15, true, 149, null),
  ('e75d66d7-c396-5dbe-b9b2-575a6842cbca', '22222222-2222-2222-2222-222222222211', 'short', '𝑠⩽2.', null, '', '', '数学/第1章 算术3 合订版.pdf', 15, true, 150, null),
  ('ea4a3bef-fb69-508d-bcef-58998184ccde', '22222222-2222-2222-2222-222222222211', 'short', '𝑠> 2. 题型2：考查等号成立时的情况', null, '', '', '数学/第1章 算术3 合订版.pdf', 15, true, 151, null),
  ('8ea63c36-04e4-517a-be4d-d2f394ba3a8a', '22222222-2222-2222-2222-222222222211', 'short', '已知𝑥, 𝑦是实数，则|𝑥| + |𝑦| = |𝑥−𝑦|.', null, '', '', '数学/第1章 算术3 合订版.pdf', 15, true, 152, null),
