  ('0466702c-3789-5883-bf0d-af8246d50294', '22222222-2222-2222-2222-222222222211', 'short', '|𝑎| + |𝑏| ⩽1.', null, '', '', '数学/第1章 算术3 合订版.pdf', 17, true, 155, null),
  ('dff01b3d-0153-58ca-be79-1102c018240d', '22222222-2222-2222-2222-222222222211', 'short', '|𝑎−𝑏| + |𝑎+ 𝑏| ⩽1.', null, '', '', '数学/第1章 算术3 合订版.pdf', 17, true, 156, null),
  ('7f295bdc-4f03-5554-8ad3-cba7711dfc06', '22222222-2222-2222-2222-222222222211', 'short', 'max{|𝑎|, |𝑏|} ⩽1.', null, '', '', '数学/第1章 算术3 合订版.pdf', 17, true, 157, null),
  ('a945ebaf-aa22-5af2-b7b9-c3c553aae033', '22222222-2222-2222-2222-222222222211', 'short', '已知𝑎, 𝑏是实数，则|𝑎| ⩽1, |𝑏| ⩽1.', null, '', '', '数学/第1章 算术3 合订版.pdf', 17, true, 158, null),
